// Generated by scripts/sync-examples.ts from scripts/example-app. Do not edit.
// expo-device's constants, implemented in Lucent per platform (M2.1 parity port):
// DeviceModule.swift and DeviceModule.kt. UIKit is main-thread only, so they
// are read with one async call.
import { PLATFORM } from "lucent:platform";
import { ProcessInfo } from "lucent:ios/Foundation";
import { UIDevice } from "lucent:ios/UIKit";
import { ActivityManager, ActivityManager_MemoryInfo } from "lucent:android/android.app";
import { Build, Build_VERSION } from "lucent:android/android.os";
import { appContext } from "lucent:android";
import { main } from "lucent:thread";

export type DeviceInfo = {
  brand: string | null;
  manufacturer: string | null;
  osName: string | null;
  osVersion: string | null;
  totalMemory: number | null;
};

export async function getDeviceInfoAsync(): Promise<DeviceInfo> {
  if (PLATFORM === "ios") {
    const os = await main(() => ({
      name: UIDevice.current.systemName,
      version: UIDevice.current.systemVersion,
    }));
    return {
      brand: "Apple",
      manufacturer: "Apple",
      osName: os.name,
      osVersion: os.version,
      totalMemory: ProcessInfo.processInfo.physicalMemory,
    };
  } else {
    const memory = new ActivityManager_MemoryInfo();
    appContext().getSystemService(ActivityManager)?.getMemoryInfo(memory);
    const baseOs = Build_VERSION.BASE_OS;
    return {
      brand: Build.BRAND,
      manufacturer: Build.MANUFACTURER,
      osName: baseOs ? baseOs : "Android",
      osVersion: Build_VERSION.RELEASE,
      totalMemory: memory.totalMem,
    };
  }
}
